export class Inbox {
    constructor(private readonly session: Session, private readonly notifications: InboxNotifications);
    get nextTurn(): readonly UserMessage[];
    get nextStep(): readonly UserMessage[];
    get hasPending(): boolean;
    clear(): void;
    claim(target: InboxTarget, turn: number): UserMessage[];
    append(target: InboxTarget, message: UserMessage): void;
    prepend(target: InboxTarget, message: UserMessage): void;
    replace(messageId: MessageId, newMessage: UserMessage): boolean;
    remove(messageId: MessageId): boolean;
    splice(target: InboxTarget, start: number, deleteCount: number, inserted: UserMessage[]): UserMessage[];
}

export interface Agent {
    readonly id: SessionId;
    readonly options: AgentOptions;
    readonly session: Session;
    readonly inbox: Inbox;
    readonly status: AgentStatus;
    readonly ctx: Context;
    cancel(cause: AgentCancelCause, options?: CancelOptions): void;
    whenIdle(): Promise<void>;
    runMaintenance<T>(task: (signal: AbortSignal) => Promise<T>): Promise<T>;
    send(message: UserMessage, target: InboxTarget, wakeup: boolean): void;
    followup(message: UserMessage): void;
    steer(message: UserMessage): void;
    inject(message: UserMessage): void;
}

export interface AgentOptions {
    provider?: string;
    model?: string;
    maxTokens?: number;
}

export interface CancelOptions {
    keepInbox?: boolean | undefined;
}

export interface ImageAttachmentRef {
    attachmentId: AttachmentId;
    mediaType: ImageMediaType;
    bytes: number;
    width: number;
    height: number;
    name?: string;
}

export type Branded<B extends string> = string & {
    readonly [BRAND]: B;
};

export interface CommandDefinition {
    readonly name: string;
    readonly description: string;
    readonly input?: CommandInputDescriptor;
    readonly recordInput?: boolean;
    readonly handler: (invocation: CommandInvocation) => CommandResult | Promise<CommandResult>;
}

export interface CommandInvocation {
    readonly commandId: CommandId;
    readonly agent: Agent;
    readonly rawInput: string;
    readonly signal: AbortSignal;
}

export class CommandRuntime extends TypertRemoteService {
    constructor(ctx: Context);
    register(definition: CommandDefinition): () => void;
    @Remote
    list(agent: Agent): readonly CommandDescriptor[];
    find(agent: Agent, name: string): CommandDefinition | undefined;
    @Remote
    async execute(agent: Agent, line: string, signal: AbortSignal): Promise<CommandExecution | undefined>;
}

export interface CommandDescriptor {
    readonly name: string;
    readonly description: string;
    readonly input?: CommandInputDescriptor;
}

export interface CommandExecution {
    readonly commandId: CommandId;
    readonly result: CommandResult;
}

export interface CommandInputDescriptor {
    readonly hint: string;
}

export type CommandResult = {
    readonly kind: 'success';
    readonly text?: string;
    readonly sourceEventSeq?: number;
} | {
    readonly kind: 'error';
    readonly text: string;
};

export interface CommandSourceMap {
    user: {
        kind: 'user';
    };
}

export class DynamicCordisRunnerService extends TypertRemoteService {
    static inject;
    static Config: z<Config>;
    constructor(ctx: Context, config: Config);
    define(request: DynamicCordisDefineRequest): DynamicCordisDefineReceipt;
    async undefine(agent: Agent, pluginId: CordisDynamicPluginId): Promise<DynamicCordisUndefineReceipt>;
    @Remote('undefineFromPanel')
    async undefineFromPanel(agent: Agent, pluginId: CordisDynamicPluginId): Promise<DynamicCordisUndefineReceipt>;
    async run(agent: Agent, pluginId: CordisDynamicPluginId, packageId: CordisDynamicPackageId, mode: CordisDynamicRunMode, signal?: AbortSignal): Promise<DynamicCordisRunResponse>;
    @Remote('runHostHalf')
    async runHostHalf(agent: Agent, pluginId: CordisDynamicPluginId, packageId: CordisDynamicPackageId, mode: CordisDynamicRunMode, requestId: ApprovalRequestId | null, approveFutureVersions: boolean): Promise<DynamicCordisHostHalfResult>;
    @Remote('getClientCode')
    getClientCode(agent: Agent, pluginId: CordisDynamicPluginId, pluginRunId: CordisDynamicPluginRunId): DynamicCordisClientSource;
    @Remote('resolveRequestRun')
    async resolveRequestRun(requestId: ApprovalRequestId, resolution: DynamicCordisRunResolution): Promise<DynamicCordisResolveAck>;
    @Remote('settleUserRun')
    async settleUserRun(agent: Agent, pluginId: CordisDynamicPluginId, resolution: DynamicCordisRunResolution): Promise<DynamicCordisRunResponse>;
    async stop(agent: Agent, pluginId: CordisDynamicPluginId): Promise<DynamicCordisStopResponse>;
    @Remote('stopFromPanel')
    async stopFromPanel(agent: Agent, pluginId: CordisDynamicPluginId): Promise<DynamicCordisStopResponse>;
    @Remote('syncInspectManifest')
    syncInspectManifest(providers: readonly CordisInspectProviderManifest[]): null;
    @Remote('resolveInspectQuery')
    resolveInspectQuery(agent: Agent, requestId: CordisInspectRequestId, resolution: CordisInspectQueryResolution): CordisInspectResolveAck;
    @Remote('inventory')
    inventory(): DynamicCordisInventoryRow[];
    snapshot(agent: Agent): DynamicCordisSnapshotRow[];
    reference(agent: Agent, pluginId: CordisDynamicPluginId): DynamicCordisReference | undefined;
    listPlugins(agent: Agent): DynamicCordisPluginInspection[];
    inspectPlugin(agent: Agent, pluginId: CordisDynamicPluginId): DynamicCordisPluginInspection;
    inspectPackage(agent: Agent, pluginId: CordisDynamicPluginId, packageId: CordisDynamicPackageId): DynamicCordisPackageInspection;
    @Remote('reportRenderFailure')
    async reportRenderFailure(agent: Agent, pluginId: CordisDynamicPluginId, pluginRunId: CordisDynamicPluginRunId, failure: DynamicCordisRenderFailure): Promise<null>;
    @Remote('reportClientGuardFailure')
    async reportClientGuardFailure(agent: Agent, pluginId: CordisDynamicPluginId, pluginRunId: CordisDynamicPluginRunId, failure: CordisErrorDetails): Promise<null>;
    @Remote('invoke')
    async invoke(pluginId: CordisDynamicPluginId, pluginRunId: CordisDynamicPluginRunId, method: string, args: JsonValue): Promise<DynamicCordisInvokeResult>;
}

export interface DynamicCordisSnapshotRow {
    pluginId: CordisDynamicPluginId;
    currentPackageId?: CordisDynamicPackageId;
    nextPackageId?: CordisDynamicPackageId;
    packages: Array<{
        packageId: CordisDynamicPackageId;
        name: string;
        purpose: string;
        hasHostHalf: boolean;
        hasClientHalf: boolean;
    }>;
    activeRun?: {
        pluginRunId: CordisDynamicPluginRunId;
        packageId: CordisDynamicPackageId;
        fiber?: Fiber;
        handlers: string[];
        renderFailure?: DynamicCordisRenderFailure;
    };
    latestRun?: DynamicCordisRunAttempt;
}

export class CordisInspectRegistryService extends Service {
    constructor(ctx: Context);
    register(registration: HostCordisInspectProviderRegistration): () => void;
    syncClientManifest(providers: readonly CordisInspectProviderManifest[]): void;
    list(): CordisInspectProviderView[];
    async query(platform: CordisInspectPlatform, providerId: string, methodName: string, input: JsonValue | undefined, agent: Agent, signal: AbortSignal): Promise<JsonValue>;
    resolveClientQuery(agent: Agent, requestId: CordisInspectRequestId, resolution: CordisInspectQueryResolution): CordisInspectResolveAck;
}

export interface HostCordisInspectProviderRegistration {
    manifest: CordisInspectProviderManifest;
    query(method: string, input: JsonValue | undefined, context: HostCordisInspectQueryContext): Promise<JsonValue>;
}

export interface HostCordisInspectQueryContext {
    signal: AbortSignal;
    agent: Agent;
}

export interface DynamicCordisDefineReceipt {
    pluginId: CordisDynamicPluginId;
    packageId: CordisDynamicPackageId;
    name: string;
    purpose: string;
    hasHostHalf: boolean;
    hasClientHalf: boolean;
}

export interface DynamicCordisDefineRequest {
    sessionId: SessionId;
    plugin: {
        kind: 'new';
        idPrefix: string;
    } | {
        kind: 'existing';
