}

export interface CordisErrorDetails {
    message: string;
    stack?: string;
}

export interface CordisHalfState {
    status: 'absent' | 'pending' | 'stopped' | 'running' | 'waiting' | 'failed';
    waitingFor: readonly string[];
    error?: string;
}

export interface CordisInspectMethodManifest {
    name: string;
    description: string;
