}

export interface CordisInspectQueryRequest {
    requestId: CordisInspectRequestId;
    agentId: SessionId;
    provider: string;
    method: string;
    input?: JsonValue;
}

export type CordisInspectQueryResolution = {
    ok: true;
    data: JsonValue;
} | {
    ok: false;
    reason: 'provider-missing' | 'method-missing' | 'invalid-input' | 'provider-error' | 'cancelled';
